use crate::{packet::{Packet,Kind},verifier,reference};
pub fn qualify(p:&Packet){assert!(reference::verify(p));assert!(verifier::verify(p));let c=&p.curve;let mut cases=vec![];let mut b=p.clone();b.target=c.add(&b.target,&p.d);cases.push(b);let mut b=p.clone();b.d=c.add(&b.d,&p.d);cases.push(b);let mut b=p.clone();b.lambda=(b.lambda+1)%p.ell;cases.push(b);let mut b=p.clone();b.rows[0].coeff[0]=(b.rows[0].coeff[0]+1)%p.ell;cases.push(b);let mut b=p.clone();b.witness[0]=(b.witness[0]+1)%p.ell;cases.push(b);let mut b=p.clone();b.k=(b.k+1)%p.ell;cases.push(b);let mut b=p.clone();let row=b.rows.iter_mut().find(|r|matches!(r.kind,Kind::Pencil{..})).unwrap();if let Kind::Pencil{points,..}=&mut row.kind{points[0].1=(points[0].1+1)%c.fp.p;}cases.push(b);for b in cases{assert!(!reference::verify(&b));assert!(!verifier::verify(&b));}}
